quests[8996] = { id = 8996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Bodley", description = "I will ignore your impertinence this time, {class}, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, {race}, you have shown courage where those that stole from me did not, and probably never could!\n\nReturn to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now.", sourceObjective = "Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning.", progress = "{name}, you're back and still alive! Well, at least that makes one of us.\n\nYou're going to have to tell me all about it!", completion = "He really said all of that? Wow, I can't believe he's going to call off the spectral assassins and stalkers, even if he did hint at causing my living companions further harm in the future.\n\nThis is a great day, {name}! You've accomplished what few ever could, and absolved us, at least in part, of some of our past sins.\n\nThank you! As a sign of appreciation, I'd like to give you this. You can use it to summon forth spirits at the same haunted locations that you already have, and a few others, too.", sourceObjectiveStatus = "unverified-source-field" }
quests[8997] = { id = 8997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Beginning", description = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Deliana in Ironforge and tell her what's happened.", sourceObjective = "Speak with Deliana at The High Seat in Ironforge.", completion = "I am very happy to see you return to me safely, {name}. You look well, if not a bit worse for the wear.\n\nCome, tell me of all that has transpired.", sourceObjectiveStatus = "unverified-source-field" }
quests[8998] = { id = 8998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Beginning", description = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Mokvar in Orgrimmar and tell him what's happened.", sourceObjective = "Speak with Mokvar at Grommash Hold in Orgrimmar's Valley of Wisdom.", completion = "I am pleased to see that you have survived, {name}. You look well, if not a bit more seasoned.\n\nCome, tell me of all that has transpired.", sourceObjectiveStatus = "unverified-source-field" }
quests[8999] = { id = 8999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "That's an amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", sourceObjective = "Give Deliana your Wildheart Cowl and Wildheart Vest.", progress = "As per our deal, are you ready to hand over your Wildheart pieces in exchange for your new Feralheart Cowl and Vest?", completion = "I'm going to miss you, {name}. I owe you such a debt of gratitude; I think I'll never be able to repay it.\n\nI hope that you enjoy your new head and chest armor, and that it protects you for a long time to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[9000] = { id = 9000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "That's an amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", sourceObjective = "Give Deliana your Beaststalker's Cap and Beaststalker's Tunic.", sourceObjectiveStatus = "unverified-source-field" }
